import{_ as i,o as a,c as t,a0 as n}from"./chunks/framework.CShDTZbC.js";const c=JSON.parse('{"title":"P2 · QMT / miniQMT 上手","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/qmt.md","filePath":"platforms/qmt.md","lastUpdated":1788573930000}'),l={name:"platforms/qmt.md"};function h(p,s,e,o,r,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="p2-·-qmt-miniqmt-上手" tabindex="-1">P2 · QMT / miniQMT 上手 <a class="header-anchor" href="#p2-·-qmt-miniqmt-上手" aria-label="Permalink to &quot;P2 · QMT / miniQMT 上手&quot;">​</a></h1><div class="ob-meta"><span class="chip">平台手册 · P2</span><span class="chip">⏱ 跟做约 60 分钟</span><span class="ob-wip">核心动线已发布 · 细节写作中</span></div><div class="tip custom-block"><p class="custom-block-title">🎯 跟完这页你能</p><ul><li>分清 QMT 和 miniQMT 到底是什么关系</li><li>走通开通 → 安装 → 拉数据的完整动线</li><li>知道 QMT 新手最容易卡住的三个地方</li></ul></div><h2 id="_1-qmt-是什么-和-miniqmt-什么关系" tabindex="-1">1. QMT 是什么，和 miniQMT 什么关系 <a class="header-anchor" href="#_1-qmt-是什么-和-miniqmt-什么关系" aria-label="Permalink to &quot;1. QMT 是什么，和 miniQMT 什么关系&quot;">​</a></h2><p><strong>QMT（迅投极速策略交易系统）是一个装在自己 Windows 电脑上的量化终端</strong>，由合作券商提供。一句话分清两兄弟：</p><ul><li><strong>QMT</strong>：完整量化终端——策略编写、回测、实盘都在这个图形界面里</li><li><strong>miniQMT</strong>：轻量独立交易端——本身不写策略，但它开放了 <code>xtquant</code> Python 库，让你<strong>在自己喜欢的编辑器里</strong>写代码、连它的行情和交易通道</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 人话翻译</p><p>QMT = 一体机的考场；miniQMT = 只借你考卷和答题卡，答题在自己家（你的 Python 环境）进行。新手先认识 QMT 本体即可。</p></div><h2 id="_2-开通与安装动线" tabindex="-1">2. 开通与安装动线 <a class="header-anchor" href="#_2-开通与安装动线" aria-label="Permalink to &quot;2. 开通与安装动线&quot;">​</a></h2><ol><li><strong>确认资格</strong>：QMT 由券商提供，各家的开通条件不同（常见与资金量或申请挂钩）。<strong>开通前先读<a href="/book/part1/ch5.html">第 5 章 · 边界与红线</a></strong>，并把&quot;只用于学习与回测&quot;作为当前阶段的自我定位</li><li><strong>联系券商</strong>：让客户经理开通 QMT 权限，拿到安装包</li><li><strong>安装登录</strong>：Windows 电脑安装 → 用券商账号登录</li><li><strong>下载历史数据</strong>（新手第一个坎，见下方坑位 1）</li></ol><h2 id="_3-第一个动作-用-xtquant-拉一份数据" tabindex="-1">3. 第一个动作：用 xtquant 拉一份数据 <a class="header-anchor" href="#_3-第一个动作-用-xtquant-拉一份数据" aria-label="Permalink to &quot;3. 第一个动作：用 xtquant 拉一份数据&quot;">​</a></h2><p>QMT 本体的策略编写在图形界面里进行；而 miniQMT 模式下，用 <code>xtquant</code> 库在自己电脑的 Python 里取数：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xtquant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xtdata</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 下载平安银行的日K历史数据（必须先下载，本地才有）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xtdata.download_history_data(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;000001.SZ&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">period</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1d&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">start_time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;20200101&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 读取刚下载的数据</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xtdata.get_market_data_ex([], [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;000001.SZ&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">period</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1d&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                                  start_time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;20240101&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">end_time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;20241231&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;000001.SZ&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].tail())   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看看最后几行</span></span></code></pre></div><p>能打印出 K 线数据，你的本地量化环境就算通了——这是 QMT 版的&quot;第 7 章时刻&quot;。</p><h2 id="_4-新手三大卡点" tabindex="-1">4. 新手三大卡点 <a class="header-anchor" href="#_4-新手三大卡点" aria-label="Permalink to &quot;4. 新手三大卡点&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">⚠️ 坑位 1：历史数据不会自动有</p><p>QMT 的行情数据<strong>需要手动下载</strong>（界面操作或 <code>download_history_data</code>）。没下载就取数，拿到的是空的——新手以为&quot;代码错了&quot;，其实只是数据没到位。</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 坑位 2：内置 Python 环境是&quot;定制的&quot;</p><p>QMT 内置特定版本的 Python 环境，和你电脑上装的 Python <strong>不是一回事</strong>。第三方库的支持范围有限，装库方式和普通环境不同。别把在外面调试好的代码直接假设它能跑。</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 坑位 3：股票代码后缀不同</p><p>QMT 用 <code>.SZ</code> / <code>.SH</code> 后缀（如 <code>000001.SZ</code>），聚宽用 <code>.XSHE</code> / <code>.XSHG</code>。跨平台抄代码时<strong>后缀必改</strong>，这是 AI 生成代码的高频翻车点（API 幻觉的表亲）。</p></div><h2 id="_5-你现在需要它吗" tabindex="-1">5. 你现在需要它吗？ <a class="header-anchor" href="#_5-你现在需要它吗" aria-label="Permalink to &quot;5. 你现在需要它吗？&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">💡 诚实的建议</p><p>如果你还处在第二篇（筑基）阶段：<strong>不需要</strong>。聚宽足以完成全部学习；QMT 的价值在本地化工程与（远期的）实盘衔接。别为了&quot;装备感&quot;提前进入复杂度。</p></div><h2 id="衔接地图" tabindex="-1">衔接地图 <a class="header-anchor" href="#衔接地图" aria-label="Permalink to &quot;衔接地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你在 QMT 遇到的事</th><th>去读</th></tr></thead><tbody><tr><td>数据下载与质检</td><td><a href="/book/part2/ch7.html">第 7 章 · 数据从哪来</a></td></tr><tr><td>代码里的未来函数嫌疑</td><td><a href="/book/part2/ch10.html">第 10 章</a> + <a href="/book/part4/ch24.html">第 24 章 · 验货进阶</a></td></tr><tr><td>跨平台代码迁移</td><td><a href="/book/part3/ch19.html">第 19 章 · AI 写策略</a>（后缀/差异让 AI 对照改）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">📋 本页自查清单</p><ul><li>[ ] 我能用一句话讲清 QMT 和 miniQMT 的区别</li><li>[ ] 我完成了开通/安装，并成功拉到一份数据（或明确知道现阶段不需要）</li><li>[ ] 我知道跨平台抄代码要改股票后缀</li></ul></div><p>→ 下一页：<a href="/platforms/ptrade.html">P3 · Ptrade 上手</a></p>`,23)])])}const g=i(l,[["render",h]]);export{c as __pageData,g as default};
